do $$begin if inet_server_addr()<>'127.0.0.1'::inet or inet_server_port()<>55498 then raise exception 'Disposable local only';end if;end$$;
do $$declare x jsonb;r jsonb;p jsonb;f uuid;j public.production_orders;old_start timestamptz;old_finish timestamptz;begin
 x:=compensation_test.fixture('ended-reject',true,true);f:=(x->>'factory')::uuid;
 select * into j from public.production_orders where id=(x->>'item')::uuid;
 r:=compensation_test.replace(x,5);
 perform compensation_test.ok(r->>'mode'='PLANNED' and (r->>'item_id')::uuid<>j.id and (select lot_id is null and group_id is null and material_request_id is null from private.manufactured_completion_work where item_id=(r->>'item_id')::uuid),'ended rejected-only replacement has no invented unfinished stock');
 perform compensation_test.ok((select po.line_id is null and po.status='planned' and pr.priority='high' from public.production_orders po join public.production_requests pr on pr.id=po.request_id where po.id=(r->>'item_id')::uuid),'replacement enters existing unscheduled HIGH queue');
 perform public.receive_manufactured_output(f,(x->>'output')::uuid,jsonb_build_object('group_id',x->>'finished','quantity','95','location','Original95 rack','physical_confirmation',true),2,gen_random_uuid());
 perform public.plan_product_item(f,(r->>'item_id')::uuid,(x->>'line')::uuid,clock_timestamp()+interval '1 day');
 perform public.start_product_item(f,(r->>'item_id')::uuid);
 p:=compensation_test.finish_output(x||jsonb_build_object('item',r->>'item_id'),5);
 perform public.finish_product_item(f,(r->>'item_id')::uuid);
 perform compensation_test.ok(private.output_demand_received(f,j.id)=95,'replacement completion and Quality do not fabricate receipt');
 perform public.receive_manufactured_output(f,(p->>'output')::uuid,jsonb_build_object('group_id',p->>'group','quantity','5','location','Replacement5 rack','physical_confirmation',true),2,gen_random_uuid());
 perform compensation_test.ok(private.output_demand_received(f,j.id)=100 and (select target_quantity=100 and actual_start=j.actual_start and actual_finish=j.actual_finish and status='completed' from public.production_orders where id=j.id),'ended replacement receives100 without reopening original');
 insert into compensation_test.contexts values('ended-result',x||jsonb_build_object('replacement',r,'replacement_output',p));
end$$;
do $$declare x jsonb;f uuid;w jsonb;r jsonb;p jsonb;j uuid;lot uuid;before_qty numeric;begin
 x:=compensation_test.fixture('mixed');f:=(x->>'factory')::uuid;j:=(x->>'item')::uuid;
 w:=public.plan_manufactured_completion(f,(x->>'output')::uuid,jsonb_build_object('group_id',x->>'unfinished','quantity','4','choice','COMPLETE','operations',jsonb_build_array(x->>'step1'),'reason','Complete four identified stored meters'),3,gen_random_uuid());
 x:=x||jsonb_build_object('revision',4);r:=compensation_test.replace(x,2);
 perform compensation_test.ok((select (private.production_compensation_state(f,(x->>'output')::uuid)->>'available')::numeric=0) and (select quantity=4 and choice='COMPLETE' from private.manufactured_completion_work where item_id=(w->>'item_id')::uuid),'complete4 plus replace2 reserve disjoint coverage');
 p:=compensation_test.finish_output(x,2);perform public.finish_product_item(f,j);
 perform public.receive_manufactured_output(f,(x->>'output')::uuid,jsonb_build_object('group_id',x->>'finished','quantity','903','location','Original903 rack','physical_confirmation',true),4,gen_random_uuid());
 perform public.receive_manufactured_output(f,(p->>'output')::uuid,jsonb_build_object('group_id',p->>'group','quantity','2','location','Replacement2 rack','physical_confirmation',true),2,gen_random_uuid());
 perform compensation_test.ok(private.output_demand_received(f,j)=905,'mixed receipt remains four short before completion');
 select lot_id into lot from private.manufactured_completion_work where item_id=(w->>'item_id')::uuid;
 perform public.plan_product_item(f,(w->>'item_id')::uuid,(x->>'line')::uuid,clock_timestamp()+interval '1 day');
 perform late_test.fails(format('select public.start_product_item(%L,%L)',f,w->>'item_id'),'output_material_not_issued');
 perform public.supply_command(f,'material_change',jsonb_build_object('id',w->>'material_request_id','revision',1,'action','issue','reason','Issue four identified meters for completion'),gen_random_uuid());
 perform compensation_test.ok((select warehouse_quantity=0 and quantity_available=4 from public.unfinished_lots where id=lot),'issue changes location only before processing');
 perform public.start_product_item(f,(w->>'item_id')::uuid);
 p:=compensation_test.finish_output(x||jsonb_build_object('item',w->>'item_id'),4,jsonb_build_object('input_lot',lot,'input_quantity',4));
 perform public.finish_product_item(f,(w->>'item_id')::uuid);
 perform compensation_test.ok((select quantity_available=0 and warehouse_quantity=0 from public.unfinished_lots where id=lot) and private.output_work_consumed(f,(w->>'item_id')::uuid)=4,'actual completion consumes exact issued four once');
 perform public.receive_manufactured_output(f,(p->>'output')::uuid,jsonb_build_object('group_id',p->>'group','quantity','4','location','Completed4 rack','physical_confirmation',true),2,gen_random_uuid());
 perform compensation_test.ok(private.output_demand_received(f,j)=909 and (select on_hand=909 from public.finished_goods_balances where factory_id=f and product_id=(x->>'product')::uuid),'mixed completion end to end receives903+2+4 exactly909');
 perform compensation_test.ok((select coalesce(sum(e.effective_scrap_kg),0)=0 from public.production_entries e where factory_id=f and order_id=(w->>'item_id')::uuid) and (select sum(quantity)=4 from public.unfinished_operations where factory_id=f and lot_id=lot),'completion ScrapKG and source operation genealogy preserved');
 insert into compensation_test.contexts values('mixed-result',x||jsonb_build_object('completion',w,'replacement',r,'completed_output',p));
end$$;
select count(*) as assertions from compensation_test.checks;
